/* SEOUL DU — warm dark / antique gold */
:root{--bg:#17110e;--panel:#211813;--panel2:#2a1d16;--gold:#c6a46a;--gold2:#ead5a5;--cream:#f3eadb;--muted:#b8a997;--line:rgba(198,164,106,.24)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--cream);font-family:"Manrope","Noto Sans Mongolian",sans-serif;overflow-x:hidden}body:before{content:"";position:fixed;inset:0;z-index:-3;background:linear-gradient(115deg,rgba(18,12,9,.94),rgba(24,15,11,.85)),url("data:image/jpeg;base64,") center/cover;opacity:.5;animation:slow-pan 36s ease-in-out infinite alternate}body:after{content:"";position:fixed;inset:0;z-index:-2;pointer-events:none;background:radial-gradient(ellipse at 80% 10%,rgba(181,119,45,.12),transparent 38%),radial-gradient(ellipse at 10% 90%,rgba(133,75,44,.14),transparent 38%),url("data:image/jpeg;base64,") center/cover;opacity:.075;mix-blend-mode:screen;animation:float-bg 42s ease-in-out infinite alternate}
@keyframes slow-pan{from{background-position:45% 50%}to{background-position:55% 46%}}@keyframes float-bg{from{transform:scale(1) translate3d(-1%,0,0)}to{transform:scale(1.08) translate3d(1%,1%,0)}}@keyframes rise{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:translateY(0)}}@keyframes drift{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-18px) rotate(12deg)}}@keyframes shimmer{0%,100%{opacity:.35;text-shadow:0 0 8px #c6a46a}50%{opacity:1;text-shadow:0 0 24px #d6b77b,0 0 48px #8e6738}}
.ambient{position:fixed;z-index:-1;width:340px;height:340px;border:1px solid rgba(198,164,106,.1);border-radius:50%;pointer-events:none}.ambient-one{top:20%;right:-250px}.ambient-two{bottom:-260px;left:-230px;width:500px;height:500px}
.site-header{height:82px;display:flex;align-items:center;justify-content:space-between;padding:0 5.2%;border-bottom:1px solid rgba(198,164,106,.17);background:rgba(20,14,11,.76);backdrop-filter:blur(16px);position:sticky;top:0;z-index:20}.brand-mini{font:600 24px "Cormorant Garamond",serif;letter-spacing:3px;color:var(--gold2);text-decoration:none}.brand-mini span{font-size:12px;color:var(--gold);vertical-align:top}.main-nav{display:flex;align-items:center;gap:clamp(10px,1.5vw,25px)}.nav-link{border:0;background:none;color:#cbbda9;font:500 10px "Manrope","Noto Sans Mongolian",sans-serif;letter-spacing:.06em;cursor:pointer;padding:12px 0;position:relative;transition:.3s}.nav-link:after{content:"";position:absolute;bottom:4px;left:0;width:0;height:1px;background:var(--gold);transition:.3s}.nav-link:hover,.nav-link.active{color:var(--gold2)}.nav-link.active:after,.nav-link:hover:after{width:100%}.header-contact{font-size:10px;letter-spacing:.08em;text-decoration:none;color:var(--gold2);border:1px solid var(--line);padding:12px 15px}.header-contact span{margin-left:8px;color:var(--gold)}.menu-toggle{display:none;background:none;border:0}.page{display:none;min-height:calc(100vh - 82px);animation:rise .7s both}.page.active{display:block}.hero{height:min(760px,calc(100vh - 82px));min-height:620px;position:relative;display:grid;place-items:center;text-align:center;overflow:hidden}.hero-image{position:absolute;inset:0;background:linear-gradient(90deg,rgba(17,11,8,.45),rgba(17,11,8,.25)),url("data:image/jpeg;base64,") center 46%/cover;filter:saturate(.72);transform:scale(1.04);animation:hero-zoom 24s ease-in-out infinite alternate}@keyframes hero-zoom{to{transform:scale(1.12) translateY(-1%)}}.hero-shade{position:absolute;inset:0;background:linear-gradient(0deg,#17110e 0%,rgba(23,17,14,.2) 38%,rgba(23,17,14,.24) 65%,#17110e 100%),radial-gradient(ellipse,rgba(18,12,8,.08),rgba(18,12,8,.72))}.hero-content{position:relative;z-index:2;padding:40px 20px;animation:rise 1.2s both}.eyebrow{font-size:9px;letter-spacing:.28em;color:var(--gold);font-weight:600}.eyebrow span{display:inline-block;width:22px;height:1px;background:var(--gold);vertical-align:middle;margin-right:10px}.hero-title{font:500 clamp(62px,10vw,136px)/.8 "Cormorant Garamond",serif;letter-spacing:.055em;margin:35px 0 8px;color:#f2e5ce;text-shadow:0 5px 40px #090604}.hero-title span{display:block}.hero-title .title-du{font-size:.8em;letter-spacing:.23em;margin-top:14px}.hangul{font:400 20px "Noto Sans Mongolian",sans-serif;letter-spacing:.3em;color:var(--gold2);margin-top:18px}.ornament{font-size:11px;letter-spacing:.35em;color:var(--gold);margin:25px 0;animation:shimmer 5s infinite}.hero-subtitle{font-size:13px;letter-spacing:.17em}.hero-copy{font:italic 19px "Cormorant Garamond",serif;color:#d0b88e;margin:12px 0 30px}.gold-button{background:linear-gradient(110deg,#b28a4f,#e0c58e);color:#21160e;border:0;padding:15px 22px;font:600 10px "Manrope",sans-serif;letter-spacing:.1em;cursor:pointer;transition:.3s}.gold-button:hover{transform:translateY(-3px);box-shadow:0 10px 30px #9a713b44}.gold-button span{margin-left:18px}.hero-bottom{position:absolute;bottom:24px;left:5%;right:5%;display:flex;justify-content:space-between;color:#bca98f;font-size:8px;letter-spacing:.2em}.floating-symbol{position:absolute;color:#d6bd8a;opacity:.55;animation:drift 7s ease-in-out infinite}.symbol-a{top:17%;left:14%;font-size:34px}.symbol-b{right:13%;top:27%;font-size:48px;animation-delay:-2s}.symbol-c{right:23%;bottom:19%;font-size:22px;animation-delay:-4s}
.section-wrap,.inner-page{padding:90px 8%}.section-kicker{color:var(--gold);font-size:9px;letter-spacing:.25em}.intro-grid{display:grid;grid-template-columns:1fr 1.25fr;gap:10%;padding-top:24px}.intro h2,.page-heading h1{font:500 clamp(42px,6vw,72px)/.98 "Cormorant Garamond",serif;margin:0;color:var(--cream)}.intro h2 em,.page-heading h1 em{color:var(--gold);font-weight:400}.intro-text{color:#c4b5a3;font-size:13px;line-height:2}.intro-text p+p{margin-top:18px}
.inner-page{max-width:1400px;margin:auto;padding-top:78px;min-height:calc(100vh - 82px)}.page-heading{text-align:center;margin:0 auto 55px;max-width:760px}.page-heading h1{margin:17px 0 12px}.page-heading>p:last-child{color:var(--muted);font-size:12px;letter-spacing:.05em}.service-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.service-card{min-height:245px;background:linear-gradient(145deg,rgba(49,34,25,.94),rgba(28,20,16,.92));border:1px solid var(--line);padding:27px;position:relative;transition:.35s;overflow:hidden}.service-card:after{content:"";position:absolute;width:130px;height:130px;border:1px solid rgba(198,164,106,.09);border-radius:50%;right:-70px;bottom:-70px;transition:.4s}.service-card:hover{transform:translateY(-6px);border-color:rgba(198,164,106,.55);background:#302219}.service-card:hover:after{transform:scale(1.5)}.service-card>span{position:absolute;right:22px;top:22px;color:#816b4e;font:16px "Cormorant Garamond",serif}.service-icon{font-size:25px;color:var(--gold);margin-bottom:18px}.service-card h3{font:600 16px "Noto Sans Mongolian",sans-serif;color:var(--gold2);margin:0 0 12px}.service-card p{font-size:11px;line-height:1.9;color:#bcae9e;margin:0}
.interior-panel{border:1px solid var(--line);padding:12px;background:#211813}.interior-photo{min-height:430px;background:linear-gradient(0deg,rgba(20,12,8,.25),transparent),url("data:image/jpeg;base64,") center/cover}.interior-caption{display:flex;justify-content:space-between;padding:15px 6px 4px;color:var(--gold);font-size:9px;letter-spacing:.16em}.note{color:#8e7f6d;font-size:10px;text-align:center;margin-top:22px}
.floor-tabs{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin-bottom:28px}.floor-tab{background:transparent;border:1px solid var(--line);color:#c4b39d;padding:12px 20px;font-size:10px;cursor:pointer;transition:.25s}.floor-tab.active,.floor-tab:hover{background:var(--gold);color:#21160e}.floor-content{display:none;max-width:1000px;margin:auto}.floor-content.active{display:block;animation:rise .4s both}.directory-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.directory-item{display:grid;grid-template-columns:55px 1fr;grid-template-rows:auto auto;align-items:center;gap:3px 12px;background:#241a14;border:1px solid rgba(198,164,106,.16);padding:15px}.directory-item b{grid-row:span 2;font:600 20px "Cormorant Garamond",serif;color:var(--gold)}.directory-item span{font-size:11px;color:#e7d9c5}.directory-item small{font-size:9px;color:#9d8971}.ward-row{display:flex;justify-content:space-between;gap:20px;padding:22px 25px;margin:9px 0;background:#241a14;border:1px solid var(--line);font-size:13px}.ward-row b{color:var(--gold);font:600 20px "Cormorant Garamond",serif}.ward-row span{color:#e3d5c2}
.price-layout{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.price-card{padding:28px;background:#241a14;border:1px solid var(--line)}.price-icon{font-size:24px;color:var(--gold)}.price-card h2{font:500 25px "Cormorant Garamond",serif;color:var(--gold2);margin:12px 0 22px}.price-row{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;padding:14px 0;border-top:1px solid rgba(198,164,106,.14);font-size:10px;color:#c4b6a5}.price-row b{font-size:10px;color:var(--gold2);text-align:right;white-space:nowrap}
.screening-list{max-width:900px;margin:auto;display:grid;grid-template-columns:1fr 1fr;gap:12px}.screening-list article{display:flex;gap:17px;padding:23px;background:#241a14;border:1px solid var(--line)}.screen-icon{font-size:24px}.screening-list h3{font-size:13px;color:var(--gold2);margin:0 0 9px}.screening-list p{font-size:11px;line-height:1.8;color:#bcae9e;margin:0}
.oath-page{display:flex;flex-direction:column;justify-content:center}.oath-card{max-width:850px;margin:auto;padding:55px 9%;text-align:center;border:1px solid rgba(198,164,106,.4);background:linear-gradient(145deg,rgba(47,32,23,.94),rgba(24,17,13,.96));position:relative}.oath-card:before,.oath-card:after{content:"✧";position:absolute;color:var(--gold);font-size:24px}.oath-card:before{top:17px;left:20px}.oath-card:after{bottom:17px;right:20px}.oath-mark{font:100px/.7 "Cormorant Garamond",serif;color:var(--gold);opacity:.65}.oath-label{font-size:9px;letter-spacing:.3em;color:var(--gold)}.oath-card blockquote{font:500 clamp(16px,2vw,22px)/1.9 "Noto Sans Mongolian",sans-serif;color:#e7dac7;margin:25px 0}.oath-seal{font:600 14px "Cormorant Garamond",serif;letter-spacing:.2em;color:var(--gold);margin-top:35px}.oath-seal span{font-size:9px}
.career-list{max-width:850px;margin:auto;display:grid;grid-template-columns:1fr 1fr;column-gap:35px}.career-list div{display:flex;align-items:center;gap:20px;padding:19px 4px;border-bottom:1px solid var(--line);transition:.25s}.career-list div:hover{padding-left:12px;color:var(--gold2)}.career-list b{font:17px "Cormorant Garamond",serif;color:var(--gold)}.career-list span{font-size:12px;flex:1}.career-list i{font-style:normal;color:var(--gold);font-size:12px}
footer{padding:55px 8% 28px;text-align:center;background:#100c09;border-top:1px solid var(--line)}.footer-brand{font:500 30px "Cormorant Garamond",serif;letter-spacing:.2em;color:var(--gold2)}.footer-brand span{font:12px "Noto Sans Mongolian",sans-serif;letter-spacing:.1em}.footer-brand+p{font-size:10px;color:#a89783;letter-spacing:.12em}.footer-line{height:1px;background:var(--line);max-width:500px;margin:28px auto}.site-footer small,footer small{display:block;color:#796b5c;font-size:8px;letter-spacing:.14em}.disclaimer{margin-top:10px;letter-spacing:0!important}
@media(max-width:1100px){.site-header{padding:0 3%}.main-nav{gap:11px}.nav-link{font-size:9px}.header-contact{display:none}.inner-page{padding-left:5%;padding-right:5%}}
@media(max-width:760px){.site-header{height:68px;padding:0 6%}.menu-toggle{display:flex;flex-direction:column;gap:6px;z-index:22;padding:10px}.menu-toggle i{display:block;width:25px;height:1px;background:var(--gold2)}.main-nav{display:none;position:absolute;top:68px;left:0;right:0;padding:20px 7% 25px;background:rgba(22,15,11,.98);border-bottom:1px solid var(--line);grid-template-columns:1fr 1fr;gap:5px 20px}.main-nav.open{display:grid}.nav-link{text-align:left;font-size:10px;padding:13px 0}.hero{min-height:620px;height:calc(88vh - 68px)}.hero-title{font-size:clamp(58px,17vw,100px)}.hero-bottom{font-size:7px}.intro-grid{grid-template-columns:1fr;gap:25px}.section-wrap{padding:65px 7%}.inner-page{padding:60px 6%}.service-grid{grid-template-columns:1fr 1fr}.service-card{padding:20px;min-height:230px}.directory-grid{grid-template-columns:1fr 1fr}.price-layout,.screening-list,.career-list{grid-template-columns:1fr}.price-row{font-size:9px}.price-row b{font-size:9px;white-space:normal}.interior-photo{min-height:280px}.interior-caption{font-size:7px}.oath-card{padding:45px 8%}.ward-row{font-size:11px}.page-heading{margin-bottom:38px}}
@media(max-width:420px){.service-grid{grid-template-columns:1fr}.directory-grid{grid-template-columns:1fr}.hero-bottom span:nth-child(2){display:none}.hero-title{letter-spacing:0}.floor-tab{padding:10px 13px}.price-card{padding:22px}}
